                output += f"{indent_str}  {key}: {type(value).__name__} of length {len(value)}\n"
            else:
                output += f"{indent_str}  {key}: {value}\n"
    return output

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys

    def inner_func(*args, **kwargs):
        if sys.version_info[0] < 3:
            return namefunc(*args, **kwargs).encode()
        else:
            return namefunc(*args, **kwargs)
    return inner_func

def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if style == 'semver':
        # Semantic Versioning style: major.minor.patch
        return '.'.join(map(str, pieces))
    elif style == 'dotted':
        # Dotted style: major.minor.patch
        return '.'.join(map(str, pieces))
    elif style == 'hyphenated':
        # Hyphenated style: major-minor-patch
        return '-'.join(map(str, pieces))
    elif style == 'spaced':
        # Spaced style: major minor patch
        return ' '.join(map(str, pieces))
    elif style == 'custom':
        # Custom style: You can define your own format here
        # Example: major_minor_patch
        return '_'.join(map(str, pieces))
    else:
        raise ValueError(f"Unsupported style: {style}")

