def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        raise ValueError("commands should be a list of strings")
    if not isinstance(args, list):
        raise ValueError("args should be a list of strings")

    full_command = commands + args
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.STDOUT
        output = subprocess.check_output(full_command, cwd=cwd, stderr=stderr_option, env=env)
        if verbose:
            print(output.decode())
        return output
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with return code {e.returncode}")
            print(e.output.decode())
        raise
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise

