def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        if isinstance(base, type):
            metaclass = type(base)
        else:
            metaclass = base.__class__

        metaclasses.add(metaclass)

    if not metaclasses:
        return type

    # If there's only one metaclass, return it
    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there are multiple metaclasses, find a common base
    common_base = None
    for m in metaclasses:
        if common_base is None:
            common_base = m
        else:
            common_base = type.__common__(common_base, m)

    if common_base is not None:
        return common_base

    raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

