def parse_diaspora_webfinger(document: str) -> Optional[Dict]:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse as JSON
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ET.fromstring(document)
            if root.tag != '{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD':
                raise ValueError("Invalid XRD document")

            # Extracting data from XRD
            data = {}
            for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                rel = link.get('rel')
                href = link.get('href')
                if rel and href:
                    data[rel] = href
            return data
        except ET.ParseError:
            logger.warning("parse_diaspora_webfinger: Failed to parse document as XRD")
        except ValueError as e:
            logger.warning(f"parse_diaspora_webfinger: {e}")

    logger.warning("parse_diaspora_webfinger: Unable to parse document")
    return None

